Here's a complete, self-contained Account Settings screen for React Native (iOS + Android), using only core RN APIs (no extra dependencies required beyond `react-native` and optionally `@react-native-async-storage` is NOT used — kept dependency-free).

```tsx
// AccountSettingsScreen.tsx
import React, { useCallback, useState } from 'react';
import {
  ActivityIndicator,
  Alert,
  Image,
  Platform,
  Pressable,
  SafeAreaView,
  ScrollView,
  StatusBar,
  StyleSheet,
  Switch,
  Text,
  View,
} from 'react-native';

// ---------- Types ----------

type NavigateItem = {
  id: string;
  type: 'navigate';
  label: string;
  value?: string;
  onPress: () => void;
};

type ToggleItem = {
  id: string;
  type: 'toggle';
  label: string;
  value: boolean;
  onToggle: (next: boolean) => void;
};

type DestructiveItem = {
  id: string;
  type: 'destructive';
  label: string;
  onPress: () => void;
};

type SettingItem = NavigateItem | ToggleItem | DestructiveItem;

type Section = {
  id: string;
  title?: string;
  items: SettingItem[];
};

type Profile = {
  name: string;
  email: string;
  avatarUrl?: string;
};

export type AccountSettingsScreenProps = {
  profile: Profile;
  onEditProfile: () => void;
  onDeleteAccount: () => Promise<void>;
  onNavigate: (destination: string) => void;
};

// ---------- Profile row ----------

function ProfileRow({
  profile,
  onPress,
}: {
  profile: Profile;
  onPress: () => void;
}) {
  const initials = profile.name
    .split(' ')
    .filter(Boolean)
    .slice(0, 2)
    .map((part) => part[0]?.toUpperCase())
    .join('');

  return (
    <Pressable
      onPress={onPress}
      accessibilityRole="button"
      accessibilityLabel={`Edit profile, ${profile.name}`}
      style={({ pressed }) => [
        styles.profileRow,
        pressed && styles.rowPressed,
      ]}
    >
      {profile.avatarUrl ? (
        <Image source={{ uri: profile.avatarUrl }} style={styles.avatar} />
      ) : (
        <View style={[styles.avatar, styles.avatarFallback]}>
          <Text style={styles.avatarInitials}>{initials || '?'}</Text>
        </View>
      )}
      <View style={styles.profileText}>
        <Text style={styles.profileName} numberOfLines={1}>
          {profile.name}
        </Text>
        <Text style={styles.profileEmail} numberOfLines={1}>
          {profile.email}
        </Text>
      </View>
      <Text style={styles.chevron}>›</Text>
    </Pressable>
  );
}

// ---------- Generic setting row ----------

function SettingRow({ item }: { item: SettingItem }) {
  if (item.type === 'toggle') {
    return (
      <View style={styles.row} accessibilityRole="switch">
        <Text style={styles.rowLabel}>{item.label}</Text>
        <Switch
          value={item.value}
          onValueChange={item.onToggle}
          accessibilityLabel={item.label}
        />
      </View>
    );
  }

  const isDestructive = item.type === 'destructive';

  return (
    <Pressable
      onPress={item.onPress}
      accessibilityRole="button"
      accessibilityLabel={item.label}
      style={({ pressed }) => [styles.row, pressed && styles.rowPressed]}
    >
      <Text style={[styles.rowLabel, isDestructive && styles.destructiveLabel]}>
        {item.label}
      </Text>
      {item.type === 'navigate' && (
        <View style={styles.rowTrailing}>
          {item.value ? (
            <Text style={styles.rowValue} numberOfLines={1}>
              {item.value}
            </Text>
          ) : null}
          <Text style={styles.chevron}>›</Text>
        </View>
      )}
    </Pressable>
  );
}

function SectionBlock({ section }: { section: Section }) {
  return (
    <View style={styles.section}>
      {section.title ? (
        <Text style={styles.sectionTitle}>{section.title}</Text>
      ) : null}
      <View style={styles.sectionCard}>
        {section.items.map((item, index) => (
          <View key={item.id}>
            <SettingRow item={item} />
            {index < section.items.length - 1 && <View style={styles.separator} />}
          </View>
        ))}
      </View>
    </View>
  );
}

// ---------- Main screen ----------

export default function AccountSettingsScreen({
  profile,
  onEditProfile,
  onDeleteAccount,
  onNavigate,
}: AccountSettingsScreenProps) {
  const [pushEnabled, setPushEnabled] = useState(true);
  const [emailUpdatesEnabled, setEmailUpdatesEnabled] = useState(false);
  const [isDeleting, setIsDeleting] = useState(false);

  const confirmDeleteAccount = useCallback(() => {
    Alert.alert(
      'Delete account',
      'This permanently deletes your account and all associated data. This cannot be undone.',
      [
        { text: 'Cancel', style: 'cancel' },
        {
          text: 'Delete',
          style: 'destructive',
          onPress: async () => {
            setIsDeleting(true);
            try {
              await onDeleteAccount();
            } catch (err) {
              Alert.alert(
                'Couldn’t delete account',
                err instanceof Error ? err.message : 'Please try again.',
              );
            } finally {
              setIsDeleting(false);
            }
          },
        },
      ],
      { cancelable: true },
    );
  }, [onDeleteAccount]);

  const sections: Section[] = [
    {
      id: 'account',
      title: 'Account',
      items: [
        { id: 'password', type: 'navigate', label: 'Password', onPress: () => onNavigate('Password') },
        { id: 'email', type: 'navigate', label: 'Email', value: profile.email, onPress: () => onNavigate('Email') },
        { id: 'privacy', type: 'navigate', label: 'Privacy', onPress: () => onNavigate('Privacy') },
      ],
    },
    {
      id: 'notifications',
      title: 'Notifications',
      items: [
        {
          id: 'push',
          type: 'toggle',
          label: 'Push notifications',
          value: pushEnabled,
          onToggle: setPushEnabled,
        },
        {
          id: 'email-updates',
          type: 'toggle',
          label: 'Email updates',
          value: emailUpdatesEnabled,
          onToggle: setEmailUpdatesEnabled,
        },
      ],
    },
    {
      id: 'support',
      title: 'Support',
      items: [
        { id: 'help', type: 'navigate', label: 'Help center', onPress: () => onNavigate('Help') },
        { id: 'terms', type: 'navigate', label: 'Terms of service', onPress: () => onNavigate('Terms') },
      ],
    },
    {
      id: 'danger',
      items: [
        {
          id: 'delete-account',
          type: 'destructive',
          label: 'Delete account',
          onPress: confirmDeleteAccount,
        },
      ],
    },
  ];

  return (
    <SafeAreaView style={styles.safeArea}>
      <StatusBar barStyle={Platform.OS === 'ios' ? 'dark-content' : 'default'} />
      <ScrollView
        contentContainerStyle={styles.scrollContent}
        keyboardShouldPersistTaps="handled"
      >
        <ProfileRow profile={profile} onPress={onEditProfile} />
        {sections.map((section) => (
          <SectionBlock key={section.id} section={section} />
        ))}
      </ScrollView>

      {isDeleting && (
        <View style={styles.overlay} accessibilityLabel="Deleting account">
          <View style={styles.overlayCard}>
            <ActivityIndicator size="large" />
            <Text style={styles.overlayText}>Deleting account…</Text>
          </View>
        </View>
      )}
    </SafeAreaView>
  );
}

// ---------- Styles ----------

const styles = StyleSheet.create({
  safeArea: {
